document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("theme-toggle"),t=document.getElementById("moon-icon"),d=document.getElementById("sun-icon"),o=localStorage.getItem("theme"),a=window.matchMedia&&window.matchMedia("(prefers-color-scheme: dark)").matches;("dark"===o||!o&&a)&&(document.body.setAttribute("data-theme","dark"),t.style.display="none",d.style.display="block"),e.addEventListener("click",()=>{"dark"===document.body.getAttribute("data-theme")?(document.body.removeAttribute("data-theme"),localStorage.setItem("theme","light"),t.style.display="block",d.style.display="none"):(document.body.setAttribute("data-theme","dark"),localStorage.setItem("theme","dark"),t.style.display="none",d.style.display="block")})});